void Solver::bump_var(int var, double coeff) {
    // Increase activity of the variable by the scaled increment.
    double inc = var_inc * coeff;
    activity[var] += inc;

    // If activity overflows, rescale all activities and the increment factor.
    if (activity[var] > 1e100) {
        const double RESCALE = 1e-100;
        for (int i = 1; i <= vars; ++i) activity[i] *= RESCALE;
        var_inc *= RESCALE;
    }

    // Keep the VSIDS heap up‑to‑date.
    if (vsids.inHeap(var)) vsids.update(var);
}
